import Box from '@mui/material/Box'
import Button from '@mui/material/Button'
import CircularProgress from '@mui/material/CircularProgress'
import TextField from '@mui/material/TextField'
import Typography from '@mui/material/Typography'
import React, { useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import api from './service/api'

const Image = () => {

  const [loading, setLoading] = useState(false)
  const [response, setResponse] = useState(null)
  const [input, setInput] = useState(null)
  console.log(response)

  const handleClick = async () => {
    setLoading(true)
    setInput(null)
    try {
      const result = await api.get("/ai/image", {
        params: {
          prompt: input
        }
      })

      const data = result.data
      setResponse(data)
    } catch (error) {
      
    }
    setLoading(false)
  }

  return (
    <Box sx={{display:"flex", alignItems:"center", flexDirection:"column"}}>
        <Typography variant='h6' sx={{mb:2}}>Gerar Imagem</Typography>
        <TextField label="Faça uma pergunta" sx={{width:"50%"}} multiline onChange={(e) => setInput(e.target.value)} />
        <Button sx={{mt:2, width:100}} variant='contained'  disabled={loading && true} onClick={handleClick}>
          {loading?  <CircularProgress size={"20px"} color='#fff'/>: "Gerar"}
        </Button>

        {/* <Box sx={{mt:3, p:3, backgroundColor:"#ccc"}}>

        
        <img src="data:image/png;base64,   "/>
        </Box> */}
          {response &&
            <Box sx={{display:"block", backgroundColor:"#ebe7e7", mt:3, width:"50%", minHeight:"50px"}}>

              
              {<img src={`data:image/png;base64, ${response}`}/>}
            </Box>
          }
      </Box>
  )
}

export default Image